css:
.card { font-family: 'Noto Sans CJK SC', 'Microsoft YaHei', sans-serif; font-size: 20px; text-align: center; color: #222; background-color: #fafafa; }
.word { font-size: 40px; font-weight: bold; margin: 20px 0 4px; }
.phonetic { font-size: 20px; color: #888; margin-bottom: 16px; }
.hr { border-top: 1px solid #ddd; margin: 16px 0; }
.sec { text-align: left; margin: 12px 0; line-height: 1.7; }
.sec .label { font-weight: bold; color: #0a6b5c; margin-right: 6px; }
.def { font-size: 22px; text-align: left; line-height: 1.6; margin: 8px 0; }
.example { color: #444; font-style: italic; }

cardTemplates.Back:
{{FrontSide}}
<hr id=answer>
{{#词根词缀}}<div class="sec"><span class="label">词根词缀</span>{{词根词缀}}</div>{{/词根词缀}}
{{#词源}}<div class="sec"><span class="label">词源</span>{{词源}}</div>{{/词源}}
<div class="def">{{释义}}</div>
{{#例句}}<div class="sec example">{{例句}}</div>{{/例句}}
